<div class="table-wrap"><table><thead><tr><th>Institusi</th><th>Kontak</th><th>Anggota</th><th>Status</th><th>Aksi</th></tr></thead><tbody>
<?php foreach($institutions as $institution): ?><tr><td><strong><?= e($institution['name']) ?></strong><small class="cell-sub"><?= e(['school'=>'Sekolah','university'=>'Perguruan tinggi','other'=>'Lainnya'][$institution['institution_type']]??'') ?> · <?= e($institution['province_name'] ? $institution['province_name'].' / '.$institution['regency_name'] : 'Daerah belum diatur') ?> · <?= e($institution['address']??'Alamat belum diisi') ?></small></td><td><?= e($institution['email']) ?><small class="cell-sub"><?= e($institution['phone']??'') ?></small></td><td><?= (int)$institution['user_count'] ?> akun · <?= (int)$institution['borrowing_count'] ?> transaksi</td><td><span class="badge status-<?= e($institution['status']==='pending'?'waiting':($institution['status']==='active'?'completed':'rejected')) ?>"><?= e(['pending'=>'Menunggu verifikasi','active'=>'Aktif','suspended'=>'Ditangguhkan'][$institution['status']]) ?></span></td><td><div class="button-row"><?php if($institution['status']==='pending'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_institution_status"><input type="hidden" name="tenant_id" value="<?= (int)$institution['id'] ?>"><input type="hidden" name="status" value="active"><button class="btn btn-success">Setujui</button></form><?php else: ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_institution_status"><input type="hidden" name="tenant_id" value="<?= (int)$institution['id'] ?>"><input type="hidden" name="status" value="<?= $institution['status']==='active'?'suspended':'active' ?>"><button class="btn btn-light"><?= $institution['status']==='active'?'Tangguhkan':'Aktifkan' ?></button></form><?php endif; ?><?php if($institution['status']==='active'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="select_institution"><input type="hidden" name="tenant_id" value="<?= (int)$institution['id'] ?>"><button class="btn btn-primary">Buka portal →</button></form><?php endif; ?></div></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section>
